-- INSERT, UPDATE, DELETE, upserts and RETURNING.
INSERT INTO t VALUES (1);
INSERT OR REPLACE INTO sch.t AS alias (a, b) SELECT 1, 2 RETURNING *;
REPLACE INTO t DEFAULT VALUES;
INSERT INTO t VALUES (1) ON CONFLICT (a, b DESC) WHERE a DO UPDATE SET x = 1, (y, z) = 2 WHERE b
  ON CONFLICT DO NOTHING;
WITH c AS (SELECT 1) INSERT INTO t SELECT * FROM c;
UPDATE OR ROLLBACK t INDEXED BY i SET a = 1 FROM u WHERE b RETURNING a AS x;
DELETE FROM t NOT INDEXED WHERE a RETURNING *;
